const X0 = -2.735384723480633;
const Y1 = 1.3823433846208855;
const S = 182.78964407016807;

/** Bujur/lintang → titik di peta (proyeksi Natural Earth I, sama dengan saat membuat path) */
export function project(lon: number, lat: number): [number, number] {
  const la = Math.max(-58, Math.min(84, lat));
  const l = (lon * Math.PI) / 180;
  const p = (la * Math.PI) / 180;
  const p2 = p * p;
  const p4 = p2 * p2;
  const x = l * (0.8707 - 0.131979 * p2 + p4 * (-0.013791 + p4 * (0.003971 * p2 - 0.001529 * p4)));
  const y = p * (1.007226 + p2 * (0.015085 + p4 * (-0.044475 + 0.028874 * p2 - 0.005916 * p4)));
  return [(x - X0) * S, (Y1 - y) * S];
}

