/** Nama negara versi FortiGate (database GeoIP) → nama di peta */
const ALIAS: Record<string, string> = {
  'united states': 'united states of america', usa: 'united states of america', 'russian federation': 'russia',
  'korea, republic of': 'south korea', 'republic of korea': 'south korea', korea: 'south korea',
  "korea, democratic people's republic of": 'north korea', 'viet nam': 'vietnam', 'iran, islamic republic of': 'iran',
  'taiwan, province of china': 'taiwan', "lao people's democratic republic": 'laos', 'syrian arab republic': 'syria',
  'moldova, republic of': 'moldova', 'tanzania, united republic of': 'united republic of tanzania', tanzania: 'united republic of tanzania',
  'congo, the democratic republic of the': 'democratic republic of the congo', 'congo, democratic republic of the': 'democratic republic of the congo',
  congo: 'republic of the congo', "cote d'ivoire": 'ivory coast', "côte d'ivoire": 'ivory coast', 'libyan arab jamahiriya': 'libya',
  'brunei darussalam': 'brunei', 'macedonia, the former yugoslav republic of': 'macedonia', 'north macedonia': 'macedonia',
  serbia: 'republic of serbia', czechia: 'czech republic', bahamas: 'the bahamas', 'timor-leste': 'east timor',
  'bolivia, plurinational state of': 'bolivia', 'venezuela, bolivarian republic of': 'venezuela', eswatini: 'swaziland',
  'palestinian territory': 'west bank', 'palestine, state of': 'west bank', palestine: 'west bank', 'guinea-bissau': 'guinea bissau',
  'great britain': 'united kingdom', uk: 'united kingdom', 'holy see (vatican city state)': 'italy', 'myanmar (burma)': 'myanmar',
  'turkiye': 'turkey', 'türkiye': 'turkey', 'falkland islands (malvinas)': 'falkland islands',
};

const BY_NAME = new Map(COUNTRIES.map((c) => [c.name.toLowerCase(), c]));
const BY_ID = new Map(COUNTRIES.map((c) => [c.id, c]));

export interface Place {
  id: string | null;
  name: string;
  lon: number;
  lat: number;
}

/** Cari titik negara dari nama versi FortiGate. null bila tidak dikenal (mis. "Reserved", "Anonymous Proxy"). */
export function findCountry(raw: string | null | undefined): Place | null {
  if (!raw) return null;
  const k = raw.trim().toLowerCase();
  if (!k || k === 'reserved' || k.includes('anonymous') || k.includes('satellite')) return null;
  const c = BY_NAME.get(ALIAS[k] ?? k) ?? BY_ID.get(raw.toUpperCase());
  if (c) return { id: c.id, name: raw, lon: c.lon, lat: c.lat };
  const s = SMALL[k];
  if (s) return { id: null, name: raw, lon: s[0], lat: s[1] };
  // "Netherlands, Kingdom of the" → "netherlands"
  const head = k.split(',')[0].trim();
  const h = BY_NAME.get(ALIAS[head] ?? head);
  return h ? { id: h.id, name: raw, lon: h.lon, lat: h.lat } : null;
}
